    return { you: you && { hp: you.hp, maxHp: you.maxHp }, weapon: E.weapon && E.weapon.name, turn: E.turn, paused: E.paused, hostiles: E.combatants.filter((o) => o.side === 'hostile').length, kills: R.kills, score: R.score, outcome: R.outcome };
  };
  // Samples HP, position and the foes near the player every `every` ms for `ms` (read-only).
  e2e.watch = (ms, every) => {
    e2e.wlog = [];
    const t0 = performance.now();
    const id = setInterval(async () => {
      const S = await import('/state/index.ts');
      const you = S.useEncounterStore.getState().combatants.find((o) => o.side !== 'hostile');
      const p = (await import('/engine/playerProbe.ts')).samplePlayer();
      const foes = e2e.foes() || [];
      const near = foes.filter((f) => p && Math.hypot(f.x - p.x, f.z - p.z) < 9);
      const inHome = foes.filter((f) => f.x >= 0 && f.x < 32 && f.z >= 0 && f.z < 32);
      e2e.wlog.push({ t: Math.round(performance.now() - t0), hp: you && you.hp, at: p && [+p.x.toFixed(2), +p.z.toFixed(2)], near: near.map((f) => [f.id, f.x, f.z, +Math.hypot(f.x - p.x, f.z - p.z).toFixed(2)]), inHome: inHome.map((f) => f.id) });
      if (performance.now() - t0 > ms) clearInterval(id);
    }, every || 250);
    return true;
  };
  e2e.watchSummary = () => {
    const l = e2e.wlog || [];
    const hps = l.map((s) => s.hp);
    const minD = {};
    for (const s of l) for (const [id, , , d] of s.near) minD[id] = Math.min(minD[id] ?? 99, d);
    return { samples: l.length, span: l.length ? l.at(-1).t : 0, hpFirst: hps[0], hpLast: hps.at(-1), hpMin: Math.min(...hps), hpChanges: hps.filter((h, i) => i > 0 && h !== hps[i - 1]).length, inHomeEver: [...new Set(l.flatMap((s) => s.inHome))], maxPlayerZ: Math.max(...l.map((s) => s.at ? s.at[1] : 0)), minFoeDistance: minD, first: l[0] && l[0].near, last: l.at(-1) && l.at(-1).near };
  };
  e2e.gridAt = () => { const b = e2e.gridBody(); return b && [b.to.x, b.to.z]; };
  if (!e2e.toastHooked) {
    e2e.toastHooked = true;
    e2e.toastLog = [];
    import('/state/index.ts').then((S) => S.useSessionStore.subscribe((st, prev) => {
      for (const t of st.toasts) if (!prev.toasts.some((p) => p.id === t.id)) e2e.toastLog.push({ at: Date.now(), tone: t.tone, text: t.text });
    }));
  }
  return Object.keys(e2e);
})()
